import Foundation

// The lesson data the interactive player runs. Authored as typed Swift values
// (see `Content/`), checked at runtime by `LessonValidator`, and never
// generated by a model: everything a learner taps on and every piece of
// objective feedback is ready before they tap.

/// One interactive lesson, at one content version.
public struct LessonContent: Sendable, Equatable {
    /// The schema these values follow. Bump when the shape changes in a way an
    /// older attempt record can't read.
    public static let currentSchemaVersion = 1

    /// The curriculum's lesson id (`u1_l3`, `b1_l1`): the same id progress,
    /// sync and certificates use, so completing here completes the lesson.
    public let lessonId: String
    /// Bumped whenever learner-visible content changes. An attempt is pinned to
    /// the version it started on.
    public let contentVersion: Int
    public let schemaVersion: Int
    public let title: String
    /// What the learner will be able to do (authored; shown on the finish step's
    /// summary and used by the validator's checks).
    public let objective: String
    /// Lesson ids that must be completed first. Mirrors the curriculum's
    /// sequential gating (`CurriculumProgressStore.isLessonUnlocked`), which
    /// stays the gate in the app; recorded here so the data says it too.
    public let prerequisites: [String]
    public let steps: [LessonStep]
    /// How the lesson completes (see `CompletionRule`).
    public let completion: CompletionRule

    public init(
        lessonId: String,
        contentVersion: Int,
        schemaVersion: Int = LessonContent.currentSchemaVersion,
        title: String,
        objective: String,
        prerequisites: [String],
        steps: [LessonStep],
        completion: CompletionRule
    ) {
        self.lessonId = lessonId
        self.contentVersion = contentVersion
        self.schemaVersion = schemaVersion
        self.title = title
        self.objective = objective
        self.prerequisites = prerequisites
        self.steps = steps
        self.completion = completion
    }

    public func step(id: String) -> LessonStep? { steps.first { $0.id == id } }
    public func index(ofStep id: String) -> Int? { steps.firstIndex { $0.id == id } }

    /// Steps the learner must finish (activities and teaching steps marked
    /// required). Progress through required work is what the player shows.
    public var requiredSteps: [LessonStep] { steps.filter(\.required) }
}

/// What has to be true for the lesson to complete. The player never completes
/// a lesson on an ungraded answer (`GradingStatus.pending` / `.ungraded`).
public struct CompletionRule: Sendable, Equatable {
    /// Step ids whose activity must end correct (after any retries or a
    /// reveal) for the lesson to complete. Activities not listed only need
    /// an answer (Basics' "a wrong pick still completes").
    public let mustBeCorrect: [String]
    /// Step ids that only need an answer submitted.
    public let mustBeAnswered: [String]

    public init(mustBeCorrect: [String], mustBeAnswered: [String] = []) {
        self.mustBeCorrect = mustBeCorrect
        self.mustBeAnswered = mustBeAnswered
    }
}

/// One screen of the lesson.
public struct LessonStep: Sendable, Equatable, Identifiable {
    public let id: String
    public let kind: StepKind
    /// Counts toward the progress shown to the learner and must be finished.
    public let required: Bool
    /// Optional depth the learner can open in place: "Why?", "Show an example",
    /// and staged "Go deeper" material. Never required, never graded.
    public let depth: [DepthItem]

    public init(id: String, kind: StepKind, required: Bool = true, depth: [DepthItem] = []) {
        self.id = id
        self.kind = kind
        self.required = required
        self.depth = depth
    }

    public var activity: Activity? {
        if case .activity(let a) = kind { return a }
        return nil
    }
}

public enum StepKind: Sendable, Equatable {
    /// A brief teaching step: a short explanation and an optional key idea.
    case teach(TeachContent)
    /// A learner decision or an original response.
    case activity(Activity)
    /// The lesson's close: what was practiced and what comes next.
    case finish(FinishContent)
}

public struct TeachContent: Sendable, Equatable {
    public let heading: String
    public let body: String
    /// One sentence to remember, shown as a key-idea card.
    public let keyIdea: String?
    public init(heading: String, body: String, keyIdea: String? = nil) {
        self.heading = heading
        self.body = body
        self.keyIdea = keyIdea
    }
}

public struct FinishContent: Sendable, Equatable {
    public let heading: String
    /// A specific account of the skill practiced.
    public let practiced: String
    /// The next relevant activity, in words (the host supplies the button).
    public let next: String
    public init(heading: String, practiced: String, next: String) {
        self.heading = heading
        self.practiced = practiced
        self.next = next
    }
}

// MARK: - Material (scenarios, excerpts, evidence)

/// A piece of material a step shows: a claim, an AI response, an excerpt.
/// Every piece says whether it is real (with its source) or invented practice
/// material, and the player prints that label.
public struct Material: Sendable, Equatable {
    public let title: String?
    public let text: String
    public let origin: MaterialOrigin
    public init(title: String? = nil, text: String, origin: MaterialOrigin) {
        self.title = title
        self.text = text
        self.origin = origin
    }
}

public enum MaterialOrigin: Sendable, Equatable {
    /// Invented for practice. The player shows "Fictional practice material".
    case fictional
    /// A real case, with where it comes from.
    case real(SourceInfo)
}

public struct SourceInfo: Sendable, Equatable {
    /// How the source is cited to the learner ("Mata v. Avianca (S.D.N.Y. 2023)").
    public let citation: String
    public let year: Int?
    public init(citation: String, year: Int? = nil) {
        self.citation = citation
        self.year = year
    }
}

// MARK: - Optional depth

public struct DepthItem: Sendable, Equatable, Identifiable {
    public enum Kind: Sendable, Equatable {
        /// "Why?": the reasoning behind the answer or idea.
        case why
        /// "Show an example".
        case example
        /// A "Go deeper" stage: the more demanding cases, in order.
        case stage(Int)
    }
    public let id: String
    public let kind: Kind
    public let title: String
    public let body: String
    /// The source or fiction label for any case or figure the item cites.
    public let origin: MaterialOrigin?

    public init(id: String, kind: Kind, title: String, body: String, origin: MaterialOrigin? = nil) {
        self.id = id
        self.kind = kind
        self.title = title
        self.body = body
        self.origin = origin
    }
}
